(function(){var b=document.currentScript.src.replace(/assets\/search-index\.js.*$/,'');window.DIALMIO_INDEX=[{"u": "getting-started/", "t": "Getting started with Dialmio", "p": "Install the app, make Dialmio your phone app, sign in and turn on backup in five minutes.", "k": ""}, {"u": "getting-started/#install-the-app", "t": "Install the app", "p": "Getting started with Dialmio", "k": "Open Google Play Store on your Android phone and search Dialmio . Tap Install . Open Dialmio. The dialer is free forever — no login or signup is needed to start calling. Android only Dialmio is available for Android phones. There is no iPhone app at the moment."}, {"u": "getting-started/#make-dialmio-your-default-phone-app", "t": "Make Dialmio your default phone app", "p": "Getting started with Dialmio", "k": "Google Play lets only your default phone app see your call history. That is why Dialmio asks for this — without it, calls cannot be logged automatically. On the welcome screen tap Make Default Dialer, It's Free . In the pop-up Set Dialmio as your default phone app? select Dialmio and tap Set as default . Your normal calls work exactly the same Incoming calls, the keypad and your contacts keep work"}, {"u": "getting-started/#get-to-know-the-home-screen", "t": "Get to know the home screen", "p": "Getting started with Dialmio", "k": "Top tabs Tab What it shows Call Logs Every call with name, SIM, duration, total calls and first-call date. Each entry has Edit Reminder Remark Status History buttons plus Call, WhatsApp and SMS shortcuts. Assigned Leads assigned to you by your admin or by round-robin. WhatsApp Chats from your connected WhatsApp Business API number. Leads All leads with their status and next follow-up. Clients Paid"}, {"u": "getting-started/#sign-in", "t": "Sign in", "p": "Getting started with Dialmio", "k": "Signing in is only needed when you want backup, sync across devices or team features. Open All Tools → Login account . Choose Phone (or Email ), enter your mobile number and tap Get OTP . Enter the 6-digit code sent to your number and tap Verify & continue . On most phones the code is filled in automatically."}, {"u": "getting-started/#turn-on-backup-sync", "t": "Turn on backup & sync", "p": "Getting started with Dialmio", "k": "After sign-in Dialmio walks you through a 3-step Backup & sync setup. See Backup & sync for every option explained."}, {"u": "getting-started/#video-guide", "t": "Video guide", "p": "Getting started with Dialmio", "k": ""}, {"u": "calling/", "t": "Calling & auto dialer", "p": "Auto dial from Excel, after-call notes, call recording, follow-up alarms and missed-call callbacks.", "k": ""}, {"u": "calling/#auto-dial-from-excel", "t": "Auto dial from Excel", "p": "Calling & auto dialer", "k": "Upload a list and let Dialmio dial it for you — up to 100 numbers with one tap. No more dialling by hand. Tap Auto Dial in the bottom bar. Import your numbers from an Excel/CSV file, or pick leads already in Dialmio. Start the session. After each call, fill the after-call sheet and Dialmio moves to the next number. Tip Keep a column for the customer name in your Excel file so the caller sees who t"}, {"u": "calling/#after-call-sheet", "t": "After-call sheet", "p": "Calling & auto dialer", "k": "When a call ends, a two-tap sheet lets you save the outcome right away: set the Status , add a Remark and schedule a Reminder . You can do the same later from any call-log entry using the Status Remark Reminder buttons, and see the full timeline with History ."}, {"u": "calling/#full-customer-detail-on-every-call", "t": "Full customer detail on every call", "p": "Calling & auto dialer", "k": "When a known number calls, Dialmio shows the name, status, last note and next follow-up on screen — caller ID comes from your own records."}, {"u": "calling/#call-recording", "t": "Call recording", "p": "Calling & auto dialer", "k": "Dialmio can attach call recordings to the lead on supported Android phones. Recording availability depends on the phone model and Android version."}, {"u": "calling/#follow-up-alarms", "t": "Follow-up alarms", "p": "Calling & auto dialer", "k": "Every reminder you set rings as an alarm at the right time, and all due follow-ups are listed in the Reminders tab."}, {"u": "calling/#missed-call-callback-queue", "t": "Missed-call callback queue", "p": "Calling & auto dialer", "k": "Missed calls are collected in a callback queue so no enquiry is forgotten."}, {"u": "calling/#works-with-mobile-data-off", "t": "Works with mobile data off", "p": "Calling & auto dialer", "k": "Calling and logging work offline. Data syncs to your account the next time you are online (if backup is on)."}, {"u": "calling/#analytics", "t": "Analytics", "p": "Calling & auto dialer", "k": "See call counts, talk time and charts for any date range. Full guide: Call analytics ."}, {"u": "calling/#app-language", "t": "App language", "p": "Calling & auto dialer", "k": "Dialmio supports 40 languages. Change it from All Tools → App Language ."}, {"u": "call-analytics/", "t": "Call analytics", "p": "See total calls, talk time, connected rate and monthly charts — then export or share the report.", "k": ""}, {"u": "call-analytics/#open-analytics", "t": "Open Analytics", "p": "Call analytics", "k": "Open Dialmio and stay on the Home screen. At the bottom of the call list, tap Analytics (next to All and your SIM chips). The top of the screen shows the total calls and total talk time for the period you choose."}, {"u": "call-analytics/#choose-a-date-range-and-sim", "t": "Choose a date range and SIM", "p": "Call analytics", "k": "Tap Today , Last 7 days , This month or All time . For your own dates tap Custom , pick the start date and end date on the calendar and tap Apply . Tap a SIM chip (for example airtel or Vi India ) to see only that SIM's calls."}, {"u": "call-analytics/#summary-tab", "t": "Summary tab", "p": "Call analytics", "k": "Summary shows each number as a ring so you can read it at a glance: Ring Meaning Incoming / Outgoing Calls received and made, with talk time under each Missed Incoming calls you did not answer Connected Calls that were answered, with total talk time Unique Different phone numbers you spoke with Rejected Calls you declined Lost Lead Calls with numbers marked as lost leads Blocked / Spam Calls from "}, {"u": "call-analytics/#analysis-tab", "t": "Analysis tab", "p": "Call analytics", "k": "Tap Analysis to see the same figures as a list: total calls, incoming and outgoing (count and time), missed, rejected, connected with connect rate % , unique numbers, lost leads, blocked, spam, total talk time and WhatsApp."}, {"u": "call-analytics/#monthly-charts", "t": "Monthly charts", "p": "Call analytics", "k": "Scroll down to see two charts: Call count (per month) — incoming, outgoing, missed and rejected calls each month. Call duration (hours) — incoming and outgoing talk time each month."}, {"u": "call-analytics/#export-and-share-the-report", "t": "Export and share the report", "p": "Call analytics", "k": "Scroll to the bottom to Export calls . It exports the calls for the range you selected. Tap Excel or PDF to save the file or share it. Tap Share today's report to send today's call summary — for example to your manager on WhatsApp. Tip Use Custom with one SIM selected to check a single team member's or a single number's performance for any period."}, {"u": "call-analytics/#video-guide", "t": "Video guide", "p": "Call analytics", "k": ""}, {"u": "leads/", "t": "Leads & automation", "p": "Get leads from IndiaMART, Facebook, Google Sheets and more, distribute them round-robin and track every stage.", "k": ""}, {"u": "leads/#lead-sources", "t": "Lead sources", "p": "Leads & automation", "k": "Leads can come into Dialmio automatically from: IndiaMART enquiries Facebook / Instagram Lead Ads Google Sheets Website forms Excel / CSV import API — from any software (see Developer API ) Any caller who is not yet a lead can be added with the Add button on the call-log entry. Need help connecting a source? Our team will set up IndiaMART, Facebook Lead Ads or Google Sheets for you. Contact suppor"}, {"u": "leads/#round-robin-distribution", "t": "Round-robin distribution", "p": "Leads & automation", "k": "New leads can be shared automatically among your team one by one, so every caller gets a fair share. Assigned leads show in each caller's Assigned tab."}, {"u": "leads/#lead-statuses-fields", "t": "Lead statuses & fields", "p": "Leads & automation", "k": "Use lead statuses (for example New, Interested, Follow-up, Won, Lost) to track each stage, and custom lead fields to store anything your business needs. Leads you close without a sale can be moved to Lost Lead ."}, {"u": "leads/#paid-clients-renewals", "t": "Paid clients & renewals", "p": "Leads & automation", "k": "When a lead buys, mark them as a paid client. The Clients tab keeps your paying customers, their products/packages and renewal dates."}, {"u": "leads/#excluded-numbers", "t": "Excluded numbers", "p": "Leads & automation", "k": "Add personal numbers (family, friends) to All Tools → Excluded numbers . Their calls are never uploaded and never become leads."}, {"u": "whatsapp/", "t": "WhatsApp", "p": "Auto WhatsApp after every call, bulk campaigns and a shared inbox using your WhatsApp Business API.", "k": ""}, {"u": "whatsapp/#connect-your-whatsapp-business-api", "t": "Connect your WhatsApp Business API", "p": "WhatsApp", "k": "Dialmio works with any WhatsApp Business API provider. We recommend WappConnect , which connects in a few minutes and supports chatbot automation. Meta charges WhatsApp conversation charges are set by Meta and billed by your API provider, not by Dialmio."}, {"u": "whatsapp/#auto-whatsapp-after-the-call", "t": "Auto WhatsApp after the call", "p": "WhatsApp", "k": "Send an automatic follow-up message the moment a call ends, so no lead goes cold. Set it up from All Tools → Auto WhatsApp and pick an approved template from Templates ."}, {"u": "whatsapp/#bulk-whatsapp-campaigns", "t": "Bulk WhatsApp campaigns", "p": "WhatsApp", "k": "Tap Bulk WA to send a campaign to your leads, to contacts from your call logs, or to numbers you copy-paste. There are two send modes: Mode How it sends Use it for Server campaign (recommended) Through the Meta WhatsApp Business API Bulk messages — verified and safe for large lists One by one Opens your phone's own WhatsApp app for each number Chatting with a single lead after the 24-hour API wind"}, {"u": "whatsapp/#shared-whatsapp-inbox", "t": "Shared WhatsApp inbox", "p": "WhatsApp", "k": "Replies that come to your API number appear in the WhatsApp tab. Any chat can be converted into a lead with one tap."}, {"u": "whatsapp/#follow-up-series-drip", "t": "Follow-up series (DRIP)", "p": "WhatsApp", "k": "Create a sequence of messages that go out automatically over several days. Open All Tools → Follow-up series (DRIP) ."}, {"u": "whatsapp/#automation-with-wappconnect", "t": "Automation with WappConnect", "p": "WhatsApp", "k": "When Dialmio is connected to WappConnect, a change in lead stage can trigger a WappConnect chatbot or automation flow — for example, sending a brochure when a lead moves to Interested ."}, {"u": "backup-sync/", "t": "Backup & sync", "p": "Keep your call history and CRM data safe in your account and on every device.", "k": ""}, {"u": "backup-sync/#step-1-agree", "t": "Step 1 — Agree", "p": "Backup & sync", "k": "Read what is backed up and tap I Agree . Tap Not now to keep everything on the phone only."}, {"u": "backup-sync/#step-2-choose-what-to-back-up", "t": "Step 2 — Choose what to back up", "p": "Backup & sync", "k": "Option What it does Attendance app Syncs only attendance, location and leads. Calls and everything else stay on the phone. Which SIM's calls to back up Turn each SIM on or off. Both SIMs are on at first. Calls on a SIM turned off are never uploaded. Only calls in working hours Calls before or after your branch's working hours, or on its day off, stay on the phone. Needs a branch with working hours"}, {"u": "backup-sync/#step-3-exclude-numbers-optional", "t": "Step 3 — Exclude numbers (optional)", "p": "Backup & sync", "k": "Numbers on this list are never uploaded. Their calls and CRM data stay only on this phone. Tap Add numbers to exclude , then Skip & Finish ."}, {"u": "backup-sync/#check-sync-status", "t": "Check sync status", "p": "Backup & sync", "k": "Open All Tools → Sync settings (or Settings → Backup & sync ). The Cloud sync section shows progress for call logs, leads, follow-ups, message templates, paid clients, products, packages, attachments, lead fields and lead statuses. Pending — waiting to upload. It clears automatically when you are online. Empty — nothing to sync in that section yet. Synced — everything is up to date. Use Force full"}, {"u": "team/", "t": "Team & owner tools", "p": "Live dashboard, daily call report, selfie attendance, permissions and team plans.", "k": ""}, {"u": "team/#add-your-team", "t": "Add your team", "p": "Team & owner tools", "k": "Using Dialmio with a team? Assign leads, give each caller their own list and see everyone's calls. Open All Tools → Team plans to choose a plan and add users."}, {"u": "team/#live-dashboard", "t": "Live dashboard", "p": "Team & owner tools", "k": "See every caller's calls, talk time and lead progress in one place, live."}, {"u": "team/#automatic-daily-call-report", "t": "Automatic daily call report", "p": "Team & owner tools", "k": "Get a summary of the day's calls for each team member without asking anyone for it."}, {"u": "team/#selfie-attendance", "t": "Selfie attendance", "p": "Team & owner tools", "k": "Team members mark attendance with a selfie and location. Use the Attendance app backup option if a phone should sync only attendance, location and leads."}, {"u": "team/#permissions", "t": "Permissions", "p": "Team & owner tools", "k": "Control what each user can see and do — for example, whether callers can see other callers' leads."}, {"u": "team/#branches-working-hours", "t": "Branches & working hours", "p": "Team & owner tools", "k": "Set working hours for each branch. Phones that use Only calls in working hours will then skip personal calls made outside office time."}, {"u": "team/#unified-search", "t": "Unified search", "p": "Team & owner tools", "k": "Search a name or number once to find their calls, lead record, notes and WhatsApp chats together."}, {"u": "developer-api/", "t": "Developer API", "p": "Connect Dialmio with your own CRM or software in both directions.", "k": ""}, {"u": "developer-api/#connect-any-crm-api", "t": "Connect any CRM API", "p": "Developer API", "k": "Push leads into Dialmio from your website, CRM or any other software, and pull call and lead data out. Open All Tools → Connect any CRM API to get started."}, {"u": "developer-api/#outbound-lead-status-api", "t": "Outbound lead-status API", "p": "Developer API", "k": "Dialmio can notify your system whenever a lead's status changes. Your own CRM or WhatsApp platform can use this to run its own automation — for example, send a quotation when a lead becomes Interested . API keys & full reference Write to support@dialmio.com with your use case and we will share API access and the endpoint reference."}, {"u": "pricing/", "t": "Plans & pricing", "p": "The dialer is free forever. CRM plans start at ₹159 per user per month.", "k": ""}, {"u": "faq/", "t": "Frequently asked questions", "p": "Quick answers to the most common questions.", "k": ""}, {"u": "contact/", "t": "Contact support", "p": "Talk to the Dialmio team on WhatsApp, phone or email.", "k": ""}].map(function(x){x.u=b+x.u;return x})})();
